import os
import subprocess
from pathlib import Path

import pytest

# Isolate the audit DB for tests before the app is imported
os.environ.setdefault("TL_AUDIT_DB", str(Path(__file__).parent / "_test_audit.db"))
os.environ.setdefault("TL_MODEL_MODE", "stub")


@pytest.fixture(scope="session")
def sample_video(tmp_path_factory) -> Path:
    """3-second synthetic video with a tone, generated by ffmpeg."""
    out = tmp_path_factory.mktemp("media") / "sample.mp4"
    subprocess.run([
        "ffmpeg", "-v", "error", "-y",
        "-f", "lavfi", "-i", "testsrc=size=320x240:rate=25:duration=3",
        "-f", "lavfi", "-i", "sine=frequency=440:duration=3",
        "-shortest", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", str(out),
    ], check=True)
    return out


def pytest_sessionfinish(session, exitstatus):
    db = Path(os.environ["TL_AUDIT_DB"])
    if db.name != "_test_audit.db":
        return
    try:
        from app.main import audit
        audit.conn.close()  # Windows cannot delete a file that is still open
    except Exception:
        pass
    try:
        db.unlink(missing_ok=True)
    except PermissionError:
        pass